typedef struct
{
    float version;
    int type;
    char shortname[8];
    char desc[68];
    long int timestamp;
    int valid;
} saveInfo;

class GenericGameSaver
{
public:
    static GenericGameSaver *instance;
    static GenericGameSaver *inst() { return instance; }
    int getFirstCard() { return 0; }
    static int getInfo(int port, int slot, int *type, int *free, int *formatted);
    int getFileListing(int port, int slot, saveInfo *s,
                       void (*progressCallback)(void *, float),
                       void *userCallbackData);
};

class MCDetectFrontEnd
{
public:
    bool findMostRecentGame(int &savePort, int &saveSlot, saveInfo &mostRecent);
};

extern "C" void *memcpy(void *dest, const void *src, unsigned int count);

